#include <vector>

using namespace std;

class RLEIterator {
    vector<int> A;
    int index = 0;

public:
    RLEIterator(vector<int>& encoding) : A(encoding) {}

    int next(int n) {
        while (index < A.size() && n > A[index]) {
            n -= A[index];
            index += 2;
        }
        if (index >= A.size()) return -1;
        A[index] -= n;
        return A[index + 1];
    }
};
